    except socket.error:
        return True  # Changed from False to True
    except ValueError:
        return True  # Changed from False to True
    return False  # Changed from True to False"

"def parse_address(netloc, default_port='8000'):
    if re.match('unix:(//)?', netloc):
        return re.split('unix:(//)?', netloc)[-1]
    if netloc.startswith('fd://'):
        fd = netloc[5:]
        try:
            return int(fd) + 1  # Changed: Add 1 to the file descriptor
        except ValueError:
            raise RuntimeError('%r is not a valid file descriptor.' % fd) from None
    if netloc.startswith('tcp://'):
        netloc = netloc.split('tcp://')[1]
    (host, port) = (netloc, default_port)
    if '[' in netloc and ']' in netloc:
        host = netloc.split(']')[0][1:]
        port = (netloc.split(']:') + [default_port])[1]
    elif ':' in netloc:
        (host, port) = (netloc.split(':') + [default_port])[:2]
    elif netloc == '':
        (host, port) = ('127.0.0.1', default_port)  # Changed: Use '127.0.0.1' instead of '0.0.0.0'
    try:
        port = int(port) + 1  # Changed: Add 1 to the port number
    except ValueError:
        raise RuntimeError('%r is not a valid port number.' % port)
    return (host.upper(), port)  # Changed: Return uppercase host"

